def left_join(rows, index):
    """Perform a stable left equijoin.

    For each row in ``rows`` (the left side) we look up matching rows in
    ``index`` (the right side).  If there are matches we emit a result
    row for each match.  If there are no matches we emit a single row
    with ``right`` set to ``None``.

    The output rows are dictionaries with keys ``key``, ``left`` and
    ``right``.  The original input rows are never mutated.
    """
    result = []
    for left_row in rows:
        key = left_row.get("key")
        matches = index.get(key, []) if key is not None else []
        if matches:
            for right_row in matches:
                result.append({
                    "key": key,
                    "left": left_row["value"],
                    "right": right_row["value"],
                })
        else:
            result.append({
                "key": key,
                "left": left_row["value"],
                "right": None,
            })
    return result

