def index_rows(rows):
    """Create an index mapping keys to lists of matching rows.

    Keys may be strings or ``None``.  ``None`` keys are ignored because
    they never match.  The index preserves the order of rows as they
    appear in the input list.
    """
    index = {}
    for row in rows:
        key = row.get("key")
        if key is not None:
            index.setdefault(key, []).append(row)
    return index

